import React, { useState, useEffect } from 'react';
import { INSTRUMENTS } from '../constants';
import { Instrument, AccountSettings } from '../types';
import { DollarSign, Percent, ArrowUpCircle, ArrowDownCircle, Crosshair, Lock, Target, Square, CheckSquare } from 'lucide-react';

interface CalculatorProps { settings: AccountSettings; }
type CalcMode = 'FIXED_RISK' | 'FIXED_LOTS';

const Calculator: React.FC<CalculatorProps> = ({ settings }) => {
  const [instrument, setInstrument] = useState<Instrument>(INSTRUMENTS[0]);
  const [direction, setDirection] = useState<'BUY' | 'SELL'>('SELL');
  const [calcMode, setCalcMode] = useState<CalcMode>('FIXED_RISK');
  const [balance, setBalance] = useState<number>(settings.balance);
  const [lotSize, setLotSize] = useState<number>(0);
  const [riskAmount, setRiskAmount] = useState<number>(0);
  const [riskPercent, setRiskPercent] = useState<number>(1);
  const [entryPrice, setEntryPrice] = useState<number>(0);
  const [slEnabled, setSlEnabled] = useState(true);
  const [slPrice, setSlPrice] = useState<number>(0);
  const [slDistance, setSlDistance] = useState<number>(0);
  const [tpEnabled, setTpEnabled] = useState(true);
  const [tpPrice, setTpPrice] = useState<number>(0);
  const [tpDistance, setTpDistance] = useState<number>(0);
  const [rewardAmount, setRewardAmount] = useState<number>(0);
  const [rrRatio, setRrRatio] = useState<number>(0);

  const isIndex = instrument.type === 'INDEX';
  const unitLabel = isIndex ? 'Points' : 'Pips';

  // 225JPY uses whole points, JPY pairs use 2 decimals, others use 5
  const pricePrecision = instrument.symbol === '225JPY' ? 0 : 
                        (instrument.pipSize === 1 || instrument.symbol.includes('JPY')) ? 2 : 5;

  useEffect(() => {
    // Defaults for pairs
    const defaults: Record<string, number> = {
        'EURUSD': 1.0850, 'US30': 39000, 'NAS100': 18000, 'SPX500': 5100,
        '225JPY': 38500, 'XAUUSD': 2300, 'USDJPY': 150.00, 'EURJPY': 163.50, 'USDMXN': 17.50
    };
    setEntryPrice(defaults[instrument.symbol] || 0);

    const defaultSl = isIndex ? (instrument.symbol === '225JPY' ? 100 : 50) : (instrument.symbol === 'USDMXN' ? 500 : 20);
    setSlDistance(defaultSl);
    calculateFromRiskPercent(1, defaultSl, settings.balance);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [instrument]);

  useEffect(() => {
    if (entryPrice > 0 && slDistance > 0) {
        if (calcMode === 'FIXED_RISK') calculateFromRiskAmount(riskAmount, slDistance, balance);
        else calculateFromLots(lotSize, slDistance, balance);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entryPrice]);

  /**
   * Calculates the USD value of 1 Pip/Point movement per 1 Lot.
   */
  const getValuePerUnit = () => {
    if (instrument.type === 'FOREX') {
       const rawPipValue = instrument.contractSize * instrument.pipSize;
       if (instrument.symbol.endsWith('USD')) return rawPipValue;
       if (instrument.symbol.includes('JPY')) {
           const conversion = instrument.symbol.startsWith('USD') ? entryPrice : 150;
           return conversion > 0 ? rawPipValue / conversion : 6.67;
       }
       return 10; // Simple default
    }

    if (instrument.symbol === 'XAUUSD') return 1; 

    if (instrument.type === 'INDEX') {
        const basePointValue = instrument.contractSize * instrument.pipSize;
        // Nikkei (225JPY) is in Yen. Conversion: Point Value / USDJPY
        if (instrument.symbol === '225JPY') return basePointValue / 150; 
        return basePointValue; // US Indices are $100 per point at 100 contract size
    }

    return instrument.contractSize; 
  };

  const calculateFromRiskPercent = (pct: number, dist: number, bal: number) => {
      const risk$ = bal * (pct / 100);
      setRiskPercent(pct);
      setRiskAmount(risk$);
      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          const lots = risk$ / (dist * valPerUnit);
          setLotSize(Number(lots.toFixed(2)));
      }
  };

  const calculateFromRiskAmount = (amt: number, dist: number, bal: number) => {
      setRiskAmount(amt);
      setRiskPercent(Number(((amt / bal) * 100).toFixed(2)));
      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          const lots = amt / (dist * valPerUnit);
          setLotSize(Number(lots.toFixed(2)));
      }
  };

  const calculateFromLots = (lots: number, dist: number, bal: number) => {
      setLotSize(lots);
      if (dist > 0) {
          const valPerUnit = getValuePerUnit();
          const risk$ = lots * dist * valPerUnit;
          setRiskAmount(Number(risk$.toFixed(2)));
          setRiskPercent(Number(((risk$ / bal) * 100).toFixed(2)));
      }
  };

  const handleRiskPercentChange = (val: number) => { setCalcMode('FIXED_RISK'); calculateFromRiskPercent(val, slDistance, balance); };
  const handleRiskAmountChange = (val: number) => { setCalcMode('FIXED_RISK'); calculateFromRiskAmount(val, slDistance, balance); };
  const handleLotSizeChange = (val: number) => { setCalcMode('FIXED_LOTS'); calculateFromLots(val, slDistance, balance); };

  const handleSlDistChange = (dist: number) => {
      setSlDistance(dist);
      if (entryPrice > 0) {
          const priceDist = dist * instrument.pipSize;
          const newPrice = direction === 'BUY' ? entryPrice - priceDist : entryPrice + priceDist;
          setSlPrice(Number(newPrice.toFixed(pricePrecision)));
      }
      if (calcMode === 'FIXED_RISK') calculateFromRiskAmount(riskAmount, dist, balance);
      else calculateFromLots(lotSize, dist, balance);
  };

  const handleSlPriceChange = (price: number) => {
      setSlPrice(price);
      if (entryPrice > 0) {
          const dist = Math.abs(entryPrice - price) / instrument.pipSize;
          setSlDistance(Number(dist.toFixed(1)));
          if (calcMode === 'FIXED_RISK') calculateFromRiskAmount(dist, dist, balance);
          else calculateFromLots(lotSize, dist, balance);
      }
  };

  const handleEntryPriceChange = (price: number) => {
      setEntryPrice(price);
      if (price > 0 && slDistance > 0) {
          const slPriceDist = slDistance * instrument.pipSize;
          setSlPrice(Number((direction === 'BUY' ? price - slPriceDist : price + slPriceDist).toFixed(pricePrecision)));
      }
  };

  const handleTpDistChange = (dist: number) => {
      setTpDistance(dist);
      if (entryPrice > 0) {
          const priceDist = dist * instrument.pipSize;
          setTpPrice(Number((direction === 'BUY' ? entryPrice + priceDist : entryPrice - priceDist).toFixed(pricePrecision)));
      }
  };

  useEffect(() => {
    if (entryPrice > 0) {
        const slPriceDist = slDistance * instrument.pipSize;
        const tpPriceDist = tpDistance * instrument.pipSize;
        setSlPrice(Number((direction === 'BUY' ? entryPrice - slPriceDist : entryPrice + slPriceDist).toFixed(pricePrecision)));
        setTpPrice(Number((direction === 'BUY' ? entryPrice + tpPriceDist : entryPrice - tpPriceDist).toFixed(pricePrecision)));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [direction]);

  useEffect(() => {
      if (tpDistance > 0 && lotSize > 0) {
          const valPerUnit = getValuePerUnit();
          const reward = lotSize * tpDistance * valPerUnit;
          setRewardAmount(Number(reward.toFixed(2)));
          if (riskAmount > 0) setRrRatio(Number((reward / riskAmount).toFixed(2)));
      } else { setRewardAmount(0); setRrRatio(0); }
      // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tpDistance, lotSize, riskAmount, instrument, entryPrice]);

  return (
    <div className="w-full max-w-5xl mx-auto p-4 md:p-6 animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
            <div>
                 <h2 className="text-3xl font-serif text-white mb-1">Risk Calculator</h2>
                 <p className="text-slate-500 text-sm">Bi-directional position sizing.</p>
            </div>
             <div className="relative z-20">
                 <select 
                    value={instrument.symbol}
                    onChange={(e) => setInstrument(INSTRUMENTS.find(i => i.symbol === e.target.value) || INSTRUMENTS[0])}
                    className="appearance-none bg-slate-900 border border-slate-700 text-gold-400 font-bold py-2 px-6 pr-10 rounded-full text-sm outline-none focus:border-gold-500 transition-all cursor-pointer shadow-lg"
                 >
                    {INSTRUMENTS.map(i => <option key={i.symbol} value={i.symbol}>{i.symbol}</option>)}
                 </select>
             </div>
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-7 space-y-6">
                <div className="bg-slate-900 rounded-2xl p-5 border border-slate-800 shadow-xl space-y-5">
                    <div className="grid grid-cols-2 gap-5">
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-wider mb-2 block">Balance</label>
                            <div className="relative group">
                                <DollarSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-gold-500 transition-colors" />
                                <input type="number" value={balance} onChange={(e) => setBalance(Number(e.target.value))} className="w-full bg-slate-950 border border-slate-700 text-white pl-9 pr-3 py-3 rounded-xl font-bold outline-none focus:border-gold-500 transition-all shadow-inner" />
                            </div>
                        </div>
                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="text-[10px] uppercase text-gold-500 font-bold tracking-wider block">Lot Size</label>
                                {calcMode === 'FIXED_LOTS' && <Lock size={12} className="text-gold-500" />}
                            </div>
                            <div className="relative group">
                                <input type="number" value={lotSize} onChange={(e) => handleLotSizeChange(Number(e.target.value))} className={`w-full bg-slate-950 border text-white px-4 py-3 rounded-xl font-mono text-lg font-bold outline-none transition-all shadow-inner ${calcMode === 'FIXED_LOTS' ? 'border-gold-500/50 shadow-[0_0_10px_rgba(212,175,55,0.05)]' : 'border-slate-700 focus:border-gold-500'}`} />
                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-600 font-bold">LOTS</span>
                            </div>
                        </div>
                    </div>
                    <div className="h-px bg-slate-800 w-full" />
                    <div className="grid grid-cols-2 gap-5">
                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="text-[10px] uppercase text-rose-400 font-bold tracking-wider block">Risk ($)</label>
                                {calcMode === 'FIXED_RISK' && <Lock size={12} className="text-rose-500" />}
                            </div>
                            <div className="relative group">
                                <DollarSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600" />
                                <input type="number" value={riskAmount} onChange={(e) => handleRiskAmountChange(Number(e.target.value))} className={`w-full bg-slate-950 border text-rose-400 pl-9 pr-3 py-3 rounded-xl font-bold outline-none transition-all ${calcMode === 'FIXED_RISK' ? 'border-rose-500/40' : 'border-slate-700 focus:border-rose-500'}`} />
                            </div>
                        </div>
                        <div>
                            <div className="flex justify-between items-center mb-2">
                                <label className="text-[10px] uppercase text-slate-500 font-bold tracking-wider block">Risk (%)</label>
                            </div>
                            <div className="relative group">
                                <Percent size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-600" />
                                <input type="number" value={riskPercent} step="0.1" onChange={(e) => handleRiskPercentChange(Number(e.target.value))} className={`w-full bg-slate-950 border text-white pl-9 pr-3 py-3 rounded-xl font-bold outline-none transition-all ${calcMode === 'FIXED_RISK' ? 'border-rose-500/40' : 'border-slate-700 focus:border-rose-500'}`} />
                            </div>
                        </div>
                    </div>
                </div>
                <div className="bg-slate-900 rounded-2xl p-5 border border-slate-800 shadow-xl space-y-4">
                    <div className="flex items-end justify-between px-1">
                        <label className="text-[10px] uppercase text-slate-500 font-bold tracking-wider">Entry Price</label>
                        <span className="text-[10px] text-gold-500 bg-gold-500/10 px-2 py-0.5 rounded">{instrument.symbol} Market</span>
                    </div>
                    <div className="relative group">
                        <Crosshair className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={18} />
                        <input type="number" value={entryPrice || ''} onChange={(e) => handleEntryPriceChange(Number(e.target.value))} className="w-full bg-slate-950 border border-slate-700 text-center text-2xl font-medium text-white py-4 rounded-xl focus:ring-1 focus:ring-gold-500 focus:border-gold-500 outline-none transition-all" placeholder="0" />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <button onClick={() => setDirection('SELL')} className={`py-3 rounded-xl border transition-all duration-200 flex items-center justify-center gap-2 ${direction === 'SELL' ? 'bg-rose-500/10 border-rose-500 text-rose-500 shadow-[0_0_15px_rgba(244,63,94,0.15)]' : 'bg-slate-950 border-slate-800 text-slate-500 hover:bg-slate-800 hover:border-slate-700'}`}><ArrowDownCircle size={18} /><span className="font-bold tracking-wide">SELL</span></button>
                        <button onClick={() => setDirection('BUY')} className={`py-3 rounded-xl border transition-all duration-200 flex items-center justify-center gap-2 ${direction === 'BUY' ? 'bg-emerald-500/10 border-emerald-500 text-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.15)]' : 'bg-slate-950 border-slate-800 text-slate-500 hover:bg-slate-800 hover:border-slate-700'}`}><ArrowUpCircle size={18} /><span className="font-bold tracking-wide">BUY</span></button>
                    </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div className={`space-y-3 p-4 rounded-xl border transition-all ${slEnabled ? 'bg-slate-900 border-rose-500/30' : 'bg-slate-900 border-slate-800 opacity-50'}`}>
                        <div className="flex items-center gap-2 cursor-pointer group mb-2" onClick={() => setSlEnabled(!slEnabled)}>{slEnabled ? <CheckSquare size={16} className="text-rose-500" /> : <Square size={16} className="text-slate-600" />}<span className={`text-xs font-bold uppercase ${slEnabled ? 'text-rose-400' : 'text-slate-500'}`}>Stop Loss</span></div>
                        <div className="bg-slate-950 rounded-lg border border-slate-800 p-2 relative"><span className="text-[9px] text-slate-500 absolute top-1 left-2 uppercase">Price</span><input type="number" disabled={!slEnabled} value={slPrice || ''} onChange={(e) => handleSlPriceChange(Number(e.target.value))} className="w-full bg-transparent text-right text-white font-medium outline-none pt-3 pb-0 text-sm" placeholder="0" /></div>
                        <div className="bg-slate-950 rounded-lg border border-slate-800 p-2 relative"><span className="text-[9px] text-slate-500 absolute top-1 left-2 uppercase">{unitLabel}</span><input type="number" disabled={!slEnabled} value={slDistance || ''} onChange={(e) => handleSlDistChange(Number(e.target.value))} className="w-full bg-transparent text-right text-rose-300 font-medium outline-none pt-3 pb-0 text-sm" placeholder="0" /></div>
                    </div>
                    <div className={`space-y-3 p-4 rounded-xl border transition-all ${tpEnabled ? 'bg-slate-900 border-emerald-500/30' : 'bg-slate-900 border-slate-800 opacity-50'}`}>
                        <div className="flex items-center gap-2 cursor-pointer group mb-2" onClick={() => setTpEnabled(!tpEnabled)}>{tpEnabled ? <CheckSquare size={16} className="text-emerald-500" /> : <Square size={16} className="text-slate-600" />}<span className={`text-xs font-bold uppercase ${tpEnabled ? 'text-emerald-400' : 'text-slate-500'}`}>Take Profit</span></div>
                        <div className="bg-slate-950 rounded-lg border border-slate-800 p-2 relative"><span className="text-[9px] text-slate-500 absolute top-1 left-2 uppercase">Price</span><input type="number" disabled={!tpEnabled} value={tpPrice || ''} onChange={(e) => setTpPrice(Number(e.target.value))} className="w-full bg-transparent text-right text-white font-medium outline-none pt-3 pb-0 text-sm" placeholder="0" /></div>
                        <div className="bg-slate-950 rounded-lg border border-slate-800 p-2 relative"><span className="text-[9px] text-slate-500 absolute top-1 left-2 uppercase">{unitLabel}</span><input type="number" disabled={!tpEnabled} value={tpDistance || ''} onChange={(e) => handleTpDistChange(Number(e.target.value))} className="w-full bg-transparent text-right text-emerald-300 font-medium outline-none pt-3 pb-0 text-sm" placeholder="0" /></div>
