                        <div className="flex items-center justify-between p-4 bg-emerald-500/5 border border-emerald-500/10 rounded-xl"><div className="flex items-center gap-3"><div className="p-2 bg-emerald-500/10 rounded-lg text-emerald-500"><Target size={18} /></div><div><p className="text-[10px] uppercase text-emerald-400 font-bold">Target Profit</p><p className="text-white font-mono text-sm">Potential Gain</p></div></div><div className="text-right"><p className={`text-xl font-bold ${rewardAmount > 0 ? 'text-emerald-500' : 'text-slate-600'}`}>{rewardAmount > 0 ? `+$${rewardAmount.toFixed(2)}` : '--'}</p><p className="text-xs text-emerald-400/70">{rrRatio > 0 ? `1:${rrRatio} R:R` : ''}</p></div></div>
                    </div>
                    <div className="mt-8 pt-6 border-t border-slate-800/50"><button className={`w-full py-4 rounded-xl font-bold uppercase tracking-wider transition-all shadow-lg ${direction === 'BUY' ? 'bg-emerald-600 hover:bg-emerald-500 text-white shadow-emerald-900/20' : 'bg-rose-600 hover:bg-rose-500 text-white shadow-rose-900/20'}`}>Execute {direction} Trade</button></div>
                </div>
            </div>
        </div>
    </div>
  );
};

export default Calculator;

import React, { useState, useEffect, useMemo } from 'react';
import { INSTRUMENTS } from '../constants';
import { Instrument, AccountSettings } from '../types';
import { 
  DollarSign, 
  Percent, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Target, 
  CheckSquare,
  TrendingUp,
  Scale,
  Activity,
  Zap
} from 'lucide-react';

interface CalculatorProps {
  settings: AccountSettings;
}

type CalcMode = 'FIXED_RISK' | 'FIXED_LOTS';

const Calculator: React.FC<CalculatorProps> = ({ settings }) => {
  const [instrument, setInstrument] = useState<Instrument>(INSTRUMENTS[0]);
  const [direction, setDirection] = useState<'BUY' | 'SELL'>('SELL');
  const [calcMode, setCalcMode] = useState<CalcMode>('FIXED_RISK');
  const [balance, setBalance] = useState<number>(settings.balance);
  const [lotSize, setLotSize] = useState<number>(0.1);
  const [riskAmount, setRiskAmount] = useState<number>(100);
  const [riskPercent, setRiskPercent] = useState<number>(1);
  const [entryPrice, setEntryPrice] = useState<number>(0);

  const [slDistance, setSlDistance] = useState<number>(20);
  const [slPrice, setSlPrice] = useState<number>(0);

  const [tpDistance, setTpDistance] = useState<number>(40);
  const [tpPrice, setTpPrice] = useState<number>(0);

  const [rewardAmount, setRewardAmount] = useState<number>(0);
  const [rrRatio, setRrRatio] = useState<number>(0);

  const isIndex = instrument.type === 'INDEX';
  const unitLabel = isIndex ? 'Points' : 'Pips';

  const pricePrecision = useMemo(() => {
    if (instrument.symbol === '225JPY') return 0;
    if (instrument.symbol.includes('JPY') || instrument.pipSize === 1) return 2;
    if (instrument.symbol === 'XAUUSD') return 2;
    return 5;
  }, [instrument]);

  // Calculate the USD value of 1 Pip/Point movement per 1.00 Lot
  const getValuePerUnit = () => {
    const USDJPY_ESTIMATE = 150.00; 

    if (instrument.type === 'FOREX') {
       const rawValue = instrument.contractSize * instrument.pipSize;
       if (instrument.symbol.endsWith('USD')) return rawValue;
       if (instrument.symbol.includes('JPY')) {
           return rawValue / USDJPY_ESTIMATE;
       }
       return 10; 
    }

    if (instrument.symbol === 'XAUUSD') return 1; 

    if (instrument.type === 'INDEX') {
        const basePointValue = instrument.contractSize * instrument.pipSize;
        if (instrument.symbol === '225JPY') {
            // Nikkei: 1 point = 100 JPY. Convert JPY to USD.
            return basePointValue / USDJPY_ESTIMATE;
        }
        return basePointValue; // US Indices (US30, NAS100) = $100/pt @ 1.0 lot
    }

    return instrument.contractSize; 
  };

  const syncCalculations = (
    mode: CalcMode, 
    riskAmt: number, 
    lots: number, 
    dist: number, 
    bal: number
  ) => {
    const valPerUnit = getValuePerUnit();
    if (dist <= 0) return;

    if (mode === 'FIXED_RISK') {
      const calculatedLots = riskAmt / (dist * valPerUnit);
      setLotSize(Number(calculatedLots.toFixed(2)));
      setRiskPercent(Number(((riskAmt / bal) * 100).toFixed(2)));
    } else {
      const calculatedRisk = lots * dist * valPerUnit;
      setRiskAmount(Number(calculatedRisk.toFixed(2)));
      setRiskPercent(Number(((calculatedRisk / bal) * 100).toFixed(2)));
    }
  };

  useEffect(() => {
    const defaults: Record<string, number> = {
        'EURUSD': 1.0850, 'US30': 39500, 'NAS100': 18200, 'SPX500': 5200,
        '225JPY': 39000, 'XAUUSD': 2350, 'USDJPY': 151.00, 'EURJPY': 163.50, 'USDMXN': 16.50
    };
    const defaultSl = isIndex ? (instrument.symbol === '225JPY' ? 100 : 50) : (instrument.symbol === 'USDMXN' ? 500 : 20);
    const defaultTp = defaultSl * 2;

    const price = defaults[instrument.symbol] || 0;
    setEntryPrice(price);
    setSlDistance(defaultSl);
    setTpDistance(defaultTp);

    const valPerUnit = getValuePerUnit();
    const initRisk = balance * (riskPercent / 100);
    setRiskAmount(initRisk);
    const initLots = initRisk / (defaultSl * valPerUnit);
    setLotSize(Number(initLots.toFixed(2)));

    const slPriceDist = defaultSl * instrument.pipSize;
    const tpPriceDist = defaultTp * instrument.pipSize;
    setSlPrice(Number((direction === 'BUY' ? price - slPriceDist : price + slPriceDist).toFixed(pricePrecision)));
    setTpPrice(Number((direction === 'BUY' ? price + tpPriceDist : price - tpPriceDist).toFixed(pricePrecision)));
  }, [instrument]);

  useEffect(() => {
    const valPerUnit = getValuePerUnit();
    const reward = lotSize * tpDistance * valPerUnit;
    setRewardAmount(Number(reward.toFixed(2)));
    if (riskAmount > 0) {
      setRrRatio(Number((reward / riskAmount).toFixed(2)));
    }
  }, [tpDistance, lotSize, riskAmount, instrument]);

  const handleRiskAmountChange = (val: number) => {
    setCalcMode('FIXED_RISK');
    setRiskAmount(val);
    syncCalculations('FIXED_RISK', val, lotSize, slDistance, balance);
  };

  const handleRiskPercentChange = (val: number) => {
    setCalcMode('FIXED_RISK');
    setRiskPercent(val);
    const amt = balance * (val / 100);
    setRiskAmount(amt);
    syncCalculations('FIXED_RISK', amt, lotSize, slDistance, balance);
  };

  const handleLotChange = (val: number) => {
    setCalcMode('FIXED_LOTS');
    setLotSize(val);
    syncCalculations('FIXED_LOTS', riskAmount, val, slDistance, balance);
  };

  const handleSlDistChange = (dist: number) => {
    setSlDistance(dist);
    const priceDist = dist * instrument.pipSize;
    setSlPrice(Number((direction === 'BUY' ? entryPrice - priceDist : entryPrice + priceDist).toFixed(pricePrecision)));
    syncCalculations(calcMode, riskAmount, lotSize, dist, balance);
  };

  const handleSlPriceChange = (price: number) => {
    setSlPrice(price);
    const dist = Math.abs(entryPrice - price) / instrument.pipSize;
    setSlDistance(Number(dist.toFixed(1)));
    syncCalculations(calcMode, riskAmount, lotSize, dist, balance);
  };

  const handleTpDistChange = (dist: number) => {
    setTpDistance(dist);
    const priceDist = dist * instrument.pipSize;
    setTpPrice(Number((direction === 'BUY' ? entryPrice + priceDist : entryPrice - priceDist).toFixed(pricePrecision)));
  };

  const handleTpPriceChange = (price: number) => {
    setTpPrice(price);
    const dist = Math.abs(entryPrice - price) / instrument.pipSize;
    setTpDistance(Number(dist.toFixed(1)));
  };

  const handleEntryPriceChange = (price: number) => {
    setEntryPrice(price);
    const slP = direction === 'BUY' ? price - (slDistance * instrument.pipSize) : price + (slDistance * instrument.pipSize);
    const tpP = direction === 'BUY' ? price + (tpDistance * instrument.pipSize) : price - (tpDistance * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  };

  const toggleDirection = (dir: 'BUY' | 'SELL') => {
    setDirection(dir);
    const slP = dir === 'BUY' ? entryPrice - (slDistance * instrument.pipSize) : entryPrice + (slDistance * instrument.pipSize);
    const tpP = dir === 'BUY' ? entryPrice + (tpDistance * instrument.pipSize) : entryPrice - (tpDistance * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  };

  return (
    <div className="w-full animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
             <div className="relative w-full md:w-auto">
                 <select 
                    value={instrument.symbol}
                    onChange={(e) => setInstrument(INSTRUMENTS.find(i => i.symbol === e.target.value) || INSTRUMENTS[0])}
                    className="w-full md:w-auto appearance-none bg-slate-900 border border-slate-700 text-gold-400 font-bold py-3 px-8 pr-12 rounded-xl text-sm outline-none focus:border-gold-500 transition-all cursor-pointer shadow-lg"
                 >
                    {INSTRUMENTS.map(i => <option key={i.symbol} value={i.symbol}>{i.symbol}</option>)}
                 </select>
             </div>

             <div className="flex bg-slate-900 p-1 rounded-xl border border-slate-800 w-full md:w-auto">
                <button 
                  onClick={() => toggleDirection('SELL')} 
                  className={`flex-1 md:px-8 py-2 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${direction === 'SELL' ? 'bg-rose-500 text-white' : 'text-slate-500'}`}
                >
                  <ArrowDownCircle size={16} /> SELL
                </button>
                <button 
                  onClick={() => toggleDirection('BUY')} 
                  className={`flex-1 md:px-8 py-2 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${direction === 'BUY' ? 'bg-emerald-500 text-white' : 'text-slate-500'}`}
                >
                  <ArrowUpCircle size={16} /> BUY
                </button>
             </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-7 space-y-6">
                <div className="bg-slate-900 rounded-2xl p-6 border border-slate-800 shadow-xl space-y-6">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Account Balance</label>
                            <div className="relative">
                                <DollarSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                <input 
                                  type="number" 
                                  value={balance}
                                  onChange={(e) => setBalance(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2.5 pl-9 pr-4 text-white focus:border-gold-500 outline-none" 
                                />
                            </div>
                        </div>
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Entry Price</label>
                            <input 
                              type="number" 
                              value={entryPrice}
                              step={instrument.pipSize}
                              onChange={(e) => handleEntryPriceChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2.5 px-4 text-white focus:border-gold-500 outline-none font-mono" 
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 pt-2">
                        <div className={`${calcMode === 'FIXED_RISK' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-3 rounded-xl transition-all`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Risk Amount ($)</label>
                            <input 
                              type="number" 
                              value={riskAmount}
                              onChange={(e) => handleRiskAmountChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white focus:border-gold-500 outline-none" 
                            />
                        </div>
                        <div className={`${calcMode === 'FIXED_RISK' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-3 rounded-xl transition-all`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Risk %</label>
                            <div className="relative">
                                <Percent size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                <input 
                                  type="number" 
                                  value={riskPercent}
                                  onChange={(e) => handleRiskPercentChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white focus:border-gold-500 outline-none" 
                                />
                            </div>
                        </div>
                        <div className={`${calcMode === 'FIXED_LOTS' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-3 rounded-xl transition-all`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Lot Size</label>
                            <input 
                              type="number" 
                              step="0.01"
                              value={lotSize}
                              onChange={(e) => handleLotChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white focus:border-gold-500 outline-none font-bold text-gold-400" 
                            />
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    <div className="bg-slate-900 rounded-2xl p-6 border border-slate-800">
                        <div className="flex items-center gap-2 mb-4 text-rose-400">
                            <TrendingUp className="rotate-180" size={18} />
                            <h3 className="font-bold uppercase text-xs tracking-wider">Stop Loss</h3>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-1">Distance ({unitLabel})</label>
                                <input 
                                  type="number" 
                                  value={slDistance}
                                  onChange={(e) => handleSlDistChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white outline-none" 
                                />
                            </div>
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-1">Price</label>
                                <input 
                                  type="number" 
                                  value={slPrice}
                                  step={instrument.pipSize}
                                  onChange={(e) => handleSlPriceChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white outline-none font-mono" 
                                />
                            </div>
                        </div>
                    </div>

                    <div className="bg-slate-900 rounded-2xl p-6 border border-slate-800">
                        <div className="flex items-center gap-2 mb-4 text-emerald-400">
                            <Target size={18} />
                            <h3 className="font-bold uppercase text-xs tracking-wider">Take Profit</h3>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-1">Distance ({unitLabel})</label>
                                <input 
                                  type="number" 
                                  value={tpDistance}
                                  onChange={(e) => handleTpDistChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white outline-none" 
                                />
                            </div>
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-1">Price</label>
                                <input 
                                  type="number" 
                                  value={tpPrice}
                                  step={instrument.pipSize}
                                  onChange={(e) => handleTpPriceChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white outline-none font-mono" 
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="lg:col-span-5 space-y-6">
                <div className="bg-gradient-to-br from-slate-900 to-slate-950 rounded-2xl p-8 border border-slate-800 shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                        <Zap size={120} className="text-gold-500" />
                    </div>

                    <div className="relative z-10 space-y-8">
                        <div>
                            <h3 className="text-slate-400 text-xs font-bold uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                                <Activity size={14} className="text-gold-500" />
                                Position Summary
                            </h3>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="bg-slate-800/30 p-4 rounded-xl border border-slate-700/50">
                                    <p className="text-[10px] text-slate-500 uppercase mb-1">Potential Risk</p>
                                    <p className="text-2xl font-serif text-rose-400">${riskAmount.toLocaleString()}</p>
                                </div>
                                <div className="bg-slate-800/30 p-4 rounded-xl border border-slate-700/50">
                                    <p className="text-[10px] text-slate-500 uppercase mb-1">Potential Gain</p>
                                    <p className="text-2xl font-serif text-emerald-400">${rewardAmount.toLocaleString()}</p>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-4">
                            <div className="flex justify-between items-center pb-2 border-b border-slate-800">
                                <span className="text-sm text-slate-400">Risk/Reward Ratio</span>
                                <span className="text-xl font-bold text-gold-500">1 : {rrRatio}</span>
                            </div>
                            <div className="flex justify-between items-center pb-2 border-b border-slate-800">
                                <span className="text-sm text-slate-400">Required Lot Size</span>
                                <span className="text-xl font-bold text-white">{lotSize} <span className="text-[10px] text-slate-500 font-normal">Lots</span></span>
                            </div>
                            <div className="flex justify-between items-center pb-2 border-b border-slate-800">
                                <span className="text-sm text-slate-400">Unit Value (per Lot)</span>
                                <span className="text-sm font-mono text-slate-300">${getValuePerUnit().toFixed(2)} /{unitLabel}</span>
                            </div>
                        </div>

                        <div className="pt-4">
                            <div className="bg-gold-500/10 border border-gold-500/20 p-4 rounded-xl flex items-start gap-3">
                                <div className="p-2 bg-gold-500 rounded-lg text-slate-950">
                                    <CheckSquare size={20} />
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-gold-400 uppercase tracking-wider">Trading Edge</p>
                                    <p className="text-sm text-slate-300 leading-relaxed">
                                        {rrRatio >= 2 
                                            ? "This setup has a healthy reward ratio. Ensure your entry signal is confirmed."
                                            : "Reward is low relative to risk. Consider tightening your stop or finding a better entry."}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800 flex items-center justify-between">
                   <div className="flex items-center gap-3">
                      <Scale className="text-slate-500" size={20} />
                      <div>
                        <p className="text-[10px] text-slate-500 uppercase font-bold">Leverage Estimate</p>
                        <p className="text-xs text-slate-400">Notational Value: ${(lotSize * instrument.contractSize * entryPrice / (instrument.symbol === '225JPY' ? 150 : 1)).toLocaleString()}</p>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-xs font-bold text-white">{(lotSize * 100).toFixed(0)} units</p>
                      <p className="text-[10px] text-slate-500 uppercase">Per Standard Lot</p>
                   </div>
                </div>
            </div>
        </div>
    </div>
  );
};

export default Calculator;

import React, { useState, useEffect, useMemo } from 'react';
import { INSTRUMENTS } from '../constants';
import { Instrument, AccountSettings } from '../types';
import { 
  DollarSign, 
  Percent, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Target, 
  CheckSquare,
  TrendingUp,
  Scale,
  Activity,
  Zap
} from 'lucide-react';

interface CalculatorProps {
  settings: AccountSettings;
}

type CalcMode = 'FIXED_RISK' | 'FIXED_LOTS';

const Calculator: React.FC<CalculatorProps> = ({ settings }) => {
  const [instrument, setInstrument] = useState<Instrument>(INSTRUMENTS[0]);
  const [direction, setDirection] = useState<'BUY' | 'SELL'>('SELL');
  const [calcMode, setCalcMode] = useState<CalcMode>('FIXED_RISK');
  const [balance, setBalance] = useState<number>(settings.balance);
  const [lotSize, setLotSize] = useState<number>(0.1);
  const [riskAmount, setRiskAmount] = useState<number>(100);
  const [riskPercent, setRiskPercent] = useState<number>(1);
  const [entryPrice, setEntryPrice] = useState<number>(0);

  const [slDistance, setSlDistance] = useState<number>(20);
  const [slPrice, setSlPrice] = useState<number>(0);

  const [tpDistance, setTpDistance] = useState<number>(40);
  const [tpPrice, setTpPrice] = useState<number>(0);

  const [rewardAmount, setRewardAmount] = useState<number>(0);
  const [rrRatio, setRrRatio] = useState<number>(0);

  const isIndex = instrument.type === 'INDEX';
  const unitLabel = isIndex ? 'Points' : 'Pips';
  const isNikkei = instrument.symbol === '225JPY';

  const pricePrecision = useMemo(() => {
    if (isNikkei) return 0;
    if (instrument.symbol.includes('JPY') || instrument.pipSize === 1) return 2;
    if (instrument.symbol === 'XAUUSD') return 2;
    return 5;
  }, [instrument, isNikkei]);

  // Calculate the USD value of 1 Pip/Point movement per 1.00 Lot
  const getValuePerUnit = () => {
    const USDJPY_ESTIMATE = 150.00; 

    if (instrument.type === 'FOREX') {
       const rawValue = instrument.contractSize * instrument.pipSize;
       if (instrument.symbol.endsWith('USD')) return rawValue;
       if (instrument.symbol.includes('JPY')) {
           return rawValue / USDJPY_ESTIMATE;
       }
       return 10; 
    }

    if (instrument.symbol === 'XAUUSD') return 1; 

    if (instrument.type === 'INDEX') {
        const basePointValue = instrument.contractSize * instrument.pipSize;
        if (isNikkei) {
            // Nikkei: 1 point = 100 JPY. Convert JPY to USD.
            return basePointValue / USDJPY_ESTIMATE;
        }
        return basePointValue; // US Indices (US30, NAS100) = $100/pt @ 1.0 lot
    }

    return instrument.contractSize; 
  };

  const syncCalculations = (
    mode: CalcMode, 
    riskAmt: number, 
    lots: number, 
    dist: number, 
    bal: number
  ) => {
    const valPerUnit = getValuePerUnit();
    if (dist <= 0) return;

    if (mode === 'FIXED_RISK') {
      let calculatedLots = riskAmt / (dist * valPerUnit);

      // Special handling for Nikkei: Min 1.0 Lot, Integer increments
      if (isNikkei) {
        calculatedLots = Math.max(1, Math.round(calculatedLots));
        setLotSize(calculatedLots);
      } else {
        setLotSize(Number(calculatedLots.toFixed(2)));
      }
      setRiskPercent(Number(((riskAmt / bal) * 100).toFixed(2)));
    } else {
      const calculatedRisk = lots * dist * valPerUnit;
      setRiskAmount(Number(calculatedRisk.toFixed(2)));
      setRiskPercent(Number(((calculatedRisk / bal) * 100).toFixed(2)));
    }
  };

  useEffect(() => {
    const defaults: Record<string, number> = {
        'EURUSD': 1.0850, 'US30': 39500, 'NAS100': 18200, 'SPX500': 5200,
        '225JPY': 39000, 'XAUUSD': 2350, 'USDJPY': 151.00, 'EURJPY': 163.50, 'USDMXN': 16.50
    };
    const defaultSl = isIndex ? (isNikkei ? 100 : 50) : (instrument.symbol === 'USDMXN' ? 500 : 20);
    const defaultTp = defaultSl * 2;

    const price = defaults[instrument.symbol] || 0;
    setEntryPrice(price);
    setSlDistance(defaultSl);
    setTpDistance(defaultTp);

    const valPerUnit = getValuePerUnit();
    const initRisk = balance * (riskPercent / 100);
    setRiskAmount(initRisk);

    let initLots = initRisk / (defaultSl * valPerUnit);
    if (isNikkei) {
      initLots = Math.max(1, Math.round(initLots));
      setLotSize(initLots);
    } else {
      setLotSize(Number(initLots.toFixed(2)));
    }

    const slPriceDist = defaultSl * instrument.pipSize;
    const tpPriceDist = defaultTp * instrument.pipSize;
    setSlPrice(Number((direction === 'BUY' ? price - slPriceDist : price + slPriceDist).toFixed(pricePrecision)));
    setTpPrice(Number((direction === 'BUY' ? price + tpPriceDist : price - tpPriceDist).toFixed(pricePrecision)));
  }, [instrument]);

  useEffect(() => {
    const valPerUnit = getValuePerUnit();
    const reward = lotSize * tpDistance * valPerUnit;
    setRewardAmount(Number(reward.toFixed(2)));
    if (riskAmount > 0) {
      setRrRatio(Number((reward / riskAmount).toFixed(2)));
    }
  }, [tpDistance, lotSize, riskAmount, instrument]);

  const handleRiskAmountChange = (val: number) => {
    setCalcMode('FIXED_RISK');
    setRiskAmount(val);
    syncCalculations('FIXED_RISK', val, lotSize, slDistance, balance);
  };

  const handleRiskPercentChange = (val: number) => {
    setCalcMode('FIXED_RISK');
    setRiskPercent(val);
    const amt = balance * (val / 100);
    setRiskAmount(amt);
    syncCalculations('FIXED_RISK', amt, lotSize, slDistance, balance);
  };

  const handleLotChange = (val: number) => {
    setCalcMode('FIXED_LOTS');
    // Enforce 1.0 minimum for Nikkei
    const sanitizedVal = isNikkei ? Math.max(1, Math.round(val)) : val;
    setLotSize(sanitizedVal);
    syncCalculations('FIXED_LOTS', riskAmount, sanitizedVal, slDistance, balance);
  };

  const handleSlDistChange = (dist: number) => {
    setSlDistance(dist);
    const priceDist = dist * instrument.pipSize;
    setSlPrice(Number((direction === 'BUY' ? entryPrice - priceDist : entryPrice + priceDist).toFixed(pricePrecision)));
    syncCalculations(calcMode, riskAmount, lotSize, dist, balance);
  };

  const handleSlPriceChange = (price: number) => {
    setSlPrice(price);
    const dist = Math.abs(entryPrice - price) / instrument.pipSize;
    setSlDistance(Number(dist.toFixed(1)));
    syncCalculations(calcMode, riskAmount, lotSize, dist, balance);
  };

  const handleTpDistChange = (dist: number) => {
    setTpDistance(dist);
    const priceDist = dist * instrument.pipSize;
    setTpPrice(Number((direction === 'BUY' ? entryPrice + priceDist : entryPrice - priceDist).toFixed(pricePrecision)));
  };

  const handleTpPriceChange = (price: number) => {
    setTpPrice(price);
    const dist = Math.abs(entryPrice - price) / instrument.pipSize;
    setTpDistance(Number(dist.toFixed(1)));
  };

  const handleEntryPriceChange = (price: number) => {
    setEntryPrice(price);
    const slP = direction === 'BUY' ? price - (slDistance * instrument.pipSize) : price + (slDistance * instrument.pipSize);
    const tpP = direction === 'BUY' ? price + (tpDistance * instrument.pipSize) : price - (tpDistance * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  };

  const toggleDirection = (dir: 'BUY' | 'SELL') => {
    setDirection(dir);
    const slP = dir === 'BUY' ? entryPrice - (slDistance * instrument.pipSize) : entryPrice + (slDistance * instrument.pipSize);
    const tpP = dir === 'BUY' ? entryPrice + (tpDistance * instrument.pipSize) : entryPrice - (tpDistance * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  };

  return (
    <div className="w-full animate-fade-in">
        <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
             <div className="relative w-full md:w-auto">
                 <select 
                    value={instrument.symbol}
                    onChange={(e) => setInstrument(INSTRUMENTS.find(i => i.symbol === e.target.value) || INSTRUMENTS[0])}
                    className="w-full md:w-auto appearance-none bg-slate-900 border border-slate-700 text-gold-400 font-bold py-3 px-8 pr-12 rounded-xl text-sm outline-none focus:border-gold-500 transition-all cursor-pointer shadow-lg"
                 >
                    {INSTRUMENTS.map(i => <option key={i.symbol} value={i.symbol}>{i.symbol}</option>)}
                 </select>
             </div>

             <div className="flex bg-slate-900 p-1 rounded-xl border border-slate-800 w-full md:w-auto">
                <button 
                  onClick={() => toggleDirection('SELL')} 
                  className={`flex-1 md:px-8 py-2 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${direction === 'SELL' ? 'bg-rose-500 text-white' : 'text-slate-500'}`}
                >
                  <ArrowDownCircle size={16} /> SELL
                </button>
                <button 
                  onClick={() => toggleDirection('BUY')} 
                  className={`flex-1 md:px-8 py-2 rounded-lg font-bold text-sm transition-all flex items-center justify-center gap-2 ${direction === 'BUY' ? 'bg-emerald-500 text-white' : 'text-slate-500'}`}
                >
                  <ArrowUpCircle size={16} /> BUY
                </button>
             </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
            <div className="lg:col-span-7 space-y-6">
                <div className="bg-slate-900 rounded-2xl p-6 border border-slate-800 shadow-xl space-y-6">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Account Balance</label>
                            <div className="relative">
                                <DollarSign size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                <input 
                                  type="number" 
                                  value={balance}
                                  onChange={(e) => setBalance(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2.5 pl-9 pr-4 text-white focus:border-gold-500 outline-none" 
                                />
                            </div>
                        </div>
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Entry Price</label>
                            <input 
                              type="number" 
                              value={entryPrice}
                              step={instrument.pipSize}
                              onChange={(e) => handleEntryPriceChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2.5 px-4 text-white focus:border-gold-500 outline-none font-mono" 
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 pt-2">
                        <div className={`${calcMode === 'FIXED_RISK' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-3 rounded-xl transition-all`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Risk Amount ($)</label>
                            <input 
                              type="number" 
                              value={riskAmount}
                              onChange={(e) => handleRiskAmountChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white focus:border-gold-500 outline-none" 
                            />
                        </div>
                        <div className={`${calcMode === 'FIXED_RISK' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-3 rounded-xl transition-all`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Risk %</label>
                            <div className="relative">
                                <Percent size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                <input 
                                  type="number" 
                                  value={riskPercent}
                                  onChange={(e) => handleRiskPercentChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white focus:border-gold-500 outline-none" 
                                />
                            </div>
                        </div>
                        <div className={`${calcMode === 'FIXED_LOTS' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-3 rounded-xl transition-all`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-2 block">Lot Size</label>
                            <input 
                              type="number" 
                              step={isNikkei ? "1" : "0.01"}
                              min={isNikkei ? "1" : "0.01"}
                              value={lotSize}
                              onChange={(e) => handleLotChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white focus:border-gold-500 outline-none font-bold text-gold-400" 
                            />
                            {isNikkei && <p className="text-[9px] text-slate-500 mt-1 uppercase">Min 1.00 LS required</p>}
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                    <div className="bg-slate-900 rounded-2xl p-6 border border-slate-800">
                        <div className="flex items-center gap-2 mb-4 text-rose-400">
                            <TrendingUp className="rotate-180" size={18} />
                            <h3 className="font-bold uppercase text-xs tracking-wider">Stop Loss</h3>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-1">Distance ({unitLabel})</label>
                                <input 
                                  type="number" 
                                  value={slDistance}
                                  onChange={(e) => handleSlDistChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white outline-none" 
                                />
                            </div>
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-1">Price</label>
                                <input 
                                  type="number" 
                                  value={slPrice}
                                  step={instrument.pipSize}
                                  onChange={(e) => handleSlPriceChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white outline-none font-mono" 
                                />
                            </div>
                        </div>
                    </div>

                    <div className="bg-slate-900 rounded-2xl p-6 border border-slate-800">
                        <div className="flex items-center gap-2 mb-4 text-emerald-400">
                            <Target size={18} />
                            <h3 className="font-bold uppercase text-xs tracking-wider">Take Profit</h3>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-1">Distance ({unitLabel})</label>
                                <input 
                                  type="number" 
                                  value={tpDistance}
                                  onChange={(e) => handleTpDistChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white outline-none" 
                                />
                            </div>
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-1">Price</label>
                                <input 
                                  type="number" 
                                  value={tpPrice}
                                  step={instrument.pipSize}
                                  onChange={(e) => handleTpPriceChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-lg py-2 px-3 text-white outline-none font-mono" 
                                />
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="lg:col-span-5 space-y-6">
                <div className="bg-gradient-to-br from-slate-900 to-slate-950 rounded-2xl p-8 border border-slate-800 shadow-2xl relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                        <Zap size={120} className="text-gold-500" />
                    </div>

                    <div className="relative z-10 space-y-8">
                        <div>
                            <h3 className="text-slate-400 text-xs font-bold uppercase tracking-[0.2em] mb-4 flex items-center gap-2">
                                <Activity size={14} className="text-gold-500" />
                                Position Summary
                            </h3>
                            <div className="grid grid-cols-2 gap-4">
                                <div className="bg-slate-800/30 p-4 rounded-xl border border-slate-700/50">
                                    <p className="text-[10px] text-slate-500 uppercase mb-1">Potential Risk</p>
                                    <p className="text-2xl font-serif text-rose-400">${riskAmount.toLocaleString()}</p>
                                </div>
                                <div className="bg-slate-800/30 p-4 rounded-xl border border-slate-700/50">
                                    <p className="text-[10px] text-slate-500 uppercase mb-1">Potential Gain</p>
                                    <p className="text-2xl font-serif text-emerald-400">${rewardAmount.toLocaleString()}</p>
                                </div>
                            </div>
                        </div>

                        <div className="space-y-4">
                            <div className="flex justify-between items-center pb-2 border-b border-slate-800">
                                <span className="text-sm text-slate-400">Risk/Reward Ratio</span>
                                <span className="text-xl font-bold text-gold-500">1 : {rrRatio}</span>
                            </div>
                            <div className="flex justify-between items-center pb-2 border-b border-slate-800">
                                <span className="text-sm text-slate-400">Required Lot Size</span>
                                <span className="text-xl font-bold text-white">{lotSize.toFixed(isNikkei ? 0 : 2)} <span className="text-[10px] text-slate-500 font-normal">Lots</span></span>
                            </div>
                            <div className="flex justify-between items-center pb-2 border-b border-slate-800">
                                <span className="text-sm text-slate-400">Unit Value (per Lot)</span>
                                <span className="text-sm font-mono text-slate-300">${getValuePerUnit().toFixed(2)} /{unitLabel}</span>
                            </div>
                        </div>

                        <div className="pt-4">
                            <div className="bg-gold-500/10 border border-gold-500/20 p-4 rounded-xl flex items-start gap-3">
                                <div className="p-2 bg-gold-500 rounded-lg text-slate-950">
                                    <CheckSquare size={20} />
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-gold-400 uppercase tracking-wider">Trading Edge</p>
                                    <p className="text-sm text-slate-300 leading-relaxed">
                                        {rrRatio >= 2 
                                            ? "This setup has a healthy reward ratio. Ensure your entry signal is confirmed."
                                            : "Reward is low relative to risk. Consider tightening your stop or finding a better entry."}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800 flex items-center justify-between">
                   <div className="flex items-center gap-3">
                      <Scale className="text-slate-500" size={20} />
                      <div>
                        <p className="text-[10px] text-slate-500 uppercase font-bold">Leverage Estimate</p>
                        <p className="text-xs text-slate-400">Notational Value: ${(lotSize * instrument.contractSize * entryPrice / (isNikkei ? 150 : 1)).toLocaleString()}</p>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-xs font-bold text-white">{(lotSize * 100).toFixed(0)} units</p>
                      <p className="text-[10px] text-slate-500 uppercase">Per Standard Lot</p>
                   </div>
                </div>
            </div>
        </div>
    </div>
  );
};

export default Calculator;

import React, { useState, useEffect, useMemo } from 'react';
import { INSTRUMENTS } from '../constants';
import { Instrument, AccountSettings } from '../types';
import { 
  DollarSign, 
  Percent, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Target, 
  CheckSquare,
  TrendingUp,
  Scale,
  Activity,
  Zap
} from 'lucide-react';

interface CalculatorProps {
  settings: AccountSettings;
}

type CalcMode = 'FIXED_RISK' | 'FIXED_LOTS';

const Calculator: React.FC<CalculatorProps> = ({ settings }) => {
  const [instrument, setInstrument] = useState<Instrument>(INSTRUMENTS[0]);
  const [direction, setDirection] = useState<'BUY' | 'SELL'>('SELL');
  const [calcMode, setCalcMode] = useState<CalcMode>('FIXED_RISK');
  const [balance, setBalance] = useState<number>(settings.balance);
  const [lotSize, setLotSize] = useState<number>(0.1);
  const [riskAmount, setRiskAmount] = useState<number>(100);
  const [riskPercent, setRiskPercent] = useState<number>(1);
  const [entryPrice, setEntryPrice] = useState<number>(0);

  const [slDistance, setSlDistance] = useState<number>(20);
  const [slPrice, setSlPrice] = useState<number>(0);

  const [tpDistance, setTpDistance] = useState<number>(40);
  const [tpPrice, setTpPrice] = useState<number>(0);

  const [rewardAmount, setRewardAmount] = useState<number>(0);
  const [rrRatio, setRrRatio] = useState<number>(0);

  const isIndex = instrument.type === 'INDEX';
  const unitLabel = isIndex ? 'Points' : 'Pips';
  const isNikkei = instrument.symbol === '225JPY';

  const pricePrecision = useMemo(() => {
    if (isNikkei) return 0;
    if (instrument.symbol.includes('JPY') || instrument.pipSize === 1) return 2;
    if (instrument.symbol === 'XAUUSD') return 2;
    return 5;
  }, [instrument, isNikkei]);

  const getValuePerUnit = () => {
    const USDJPY = 150.00; 

    if (instrument.type === 'FOREX') {
       const pipValueInQuote = instrument.contractSize * instrument.pipSize;
       if (instrument.symbol.endsWith('USD')) return pipValueInQuote;
       if (instrument.symbol.includes('JPY')) return pipValueInQuote / USDJPY;
       return 10;
    }

    if (instrument.symbol === 'XAUUSD') {
        return instrument.contractSize * instrument.pipSize; 
    }

    if (instrument.type === 'INDEX') {
        const pointValueInQuote = instrument.contractSize * instrument.pipSize;
        if (isNikkei) return pointValueInQuote / USDJPY;
        return pointValueInQuote; 
    }

    return instrument.contractSize * instrument.pipSize; 
  };

  const syncCalculations = (
    mode: CalcMode, 
    riskAmt: number, 
    lots: number, 
    dist: number, 
    bal: number
  ) => {
    const valPerUnit = getValuePerUnit();
    if (dist <= 0) return;

    if (mode === 'FIXED_RISK') {
      let calculatedLots = riskAmt / (dist * valPerUnit);

      if (isNikkei) {
        // Enforce 1.00 LS Minimum and Integer steps for Nikkei
        calculatedLots = Math.max(1, Math.round(calculatedLots));
        setLotSize(calculatedLots);
        // Adjust dollar amount to reflect reality of 1.0 lot constraint
        const actualRisk = calculatedLots * dist * valPerUnit;
        setRiskAmount(Number(actualRisk.toFixed(2)));
        setRiskPercent(Number(((actualRisk / bal) * 100).toFixed(2)));
      } else {
        setLotSize(Number(calculatedLots.toFixed(2)));
        setRiskPercent(Number(((riskAmt / bal) * 100).toFixed(2)));
      }
    } else {
      const calculatedRisk = lots * dist * valPerUnit;
      setRiskAmount(Number(calculatedRisk.toFixed(2)));
      setRiskPercent(Number(((calculatedRisk / bal) * 100).toFixed(2)));
    }
  };

  useEffect(() => {
    const defaults: Record<string, number> = {
        'EURUSD': 1.0850, 'US30': 39500, 'NAS100': 18200, 'SPX500': 5200,
        '225JPY': 39000, 'XAUUSD': 2350, 'USDJPY': 151.00, 'EURJPY': 163.50, 'USDMXN': 16.50
    };

    const defaultSl = isIndex ? (isNikkei ? 100 : 50) : (instrument.symbol === 'USDMXN' ? 500 : 20);
    const defaultTp = defaultSl * 2;

    const price = defaults[instrument.symbol] || 0;
    setEntryPrice(price);
    setSlDistance(defaultSl);
    setTpDistance(defaultTp);

    const valPerUnit = getValuePerUnit();
    const initRisk = balance * (riskPercent / 100);

    let initLots = initRisk / (defaultSl * valPerUnit);
    if (isNikkei) {
      initLots = Math.max(1, Math.round(initLots));
      setLotSize(initLots);
      setRiskAmount(Number((initLots * defaultSl * valPerUnit).toFixed(2)));
    } else {
      setLotSize(Number(initLots.toFixed(2)));
      setRiskAmount(initRisk);
    }

    const slPriceDist = defaultSl * instrument.pipSize;
    const tpPriceDist = defaultTp * instrument.pipSize;
    setSlPrice(Number((direction === 'BUY' ? price - slPriceDist : price + slPriceDist).toFixed(pricePrecision)));
    setTpPrice(Number((direction === 'BUY' ? price + tpPriceDist : price - tpPriceDist).toFixed(pricePrecision)));
  }, [instrument]);

  useEffect(() => {
    const valPerUnit = getValuePerUnit();
    const reward = lotSize * tpDistance * valPerUnit;
    setRewardAmount(Number(reward.toFixed(2)));
    if (riskAmount > 0) {
      setRrRatio(Number((reward / riskAmount).toFixed(2)));
    }
  }, [tpDistance, lotSize, riskAmount, instrument]);

  const handleRiskAmountChange = (val: number) => {
    setCalcMode('FIXED_RISK');
    setRiskAmount(val);
    syncCalculations('FIXED_RISK', val, lotSize, slDistance, balance);
  };

  const handleRiskPercentChange = (val: number) => {
    setCalcMode('FIXED_RISK');
    setRiskPercent(val);
    const amt = balance * (val / 100);
    setRiskAmount(amt);
    syncCalculations('FIXED_RISK', amt, lotSize, slDistance, balance);
  };

  const handleLotChange = (val: number) => {
    setCalcMode('FIXED_LOTS');
    const sanitizedVal = isNikkei ? Math.max(1, Math.round(val)) : val;
    setLotSize(sanitizedVal);
    syncCalculations('FIXED_LOTS', riskAmount, sanitizedVal, slDistance, balance);
  };

  const handleSlDistChange = (dist: number) => {
    setSlDistance(dist);
    const priceDist = dist * instrument.pipSize;
    setSlPrice(Number((direction === 'BUY' ? entryPrice - priceDist : entryPrice + priceDist).toFixed(pricePrecision)));
    syncCalculations(calcMode, riskAmount, lotSize, dist, balance);
  };

  const handleSlPriceChange = (price: number) => {
    setSlPrice(price);
    const dist = Math.abs(entryPrice - price) / instrument.pipSize;
    setSlDistance(Number(dist.toFixed(1)));
    syncCalculations(calcMode, riskAmount, lotSize, dist, balance);
  };

  const handleTpDistChange = (dist: number) => {
    setTpDistance(dist);
    const priceDist = dist * instrument.pipSize;
    setTpPrice(Number((direction === 'BUY' ? entryPrice + priceDist : entryPrice - priceDist).toFixed(pricePrecision)));
  };

  const handleTpPriceChange = (price: number) => {
    setTpPrice(price);
    const dist = Math.abs(entryPrice - price) / instrument.pipSize;
    setTpDistance(Number(dist.toFixed(1)));
  };

  const handleEntryPriceChange = (price: number) => {
    setEntryPrice(price);
    const slP = direction === 'BUY' ? price - (slDistance * instrument.pipSize) : price + (slDistance * instrument.pipSize);
    const tpP = direction === 'BUY' ? price + (tpDistance * instrument.pipSize) : price - (tpDistance * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  };

  const toggleDirection = (dir: 'BUY' | 'SELL') => {
    setDirection(dir);
    const slP = dir === 'BUY' ? entryPrice - (slDistance * instrument.pipSize) : entryPrice + (slDistance * instrument.pipSize);
    const tpP = dir === 'BUY' ? entryPrice + (tpDistance * instrument.pipSize) : entryPrice - (tpDistance * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  };

  return (
    <div className="w-full animate-fade-in pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
             <div className="relative w-full md:w-auto">
                 <select 
                    value={instrument.symbol}
                    onChange={(e) => setInstrument(INSTRUMENTS.find(i => i.symbol === e.target.value) || INSTRUMENTS[0])}
                    className="w-full md:w-auto appearance-none bg-slate-900 border border-slate-700 text-gold-400 font-bold py-3 px-10 pr-14 rounded-xl text-sm outline-none focus:border-gold-500 transition-all cursor-pointer shadow-lg"
                 >
                    {INSTRUMENTS.map(i => <option key={i.symbol} value={i.symbol}>{i.symbol}</option>)}
                 </select>
                 <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                    <Activity size={18} />
                 </div>
             </div>

             <div className="flex bg-slate-900 p-1.5 rounded-2xl border border-slate-800 w-full md:w-auto shadow-inner">
                <button 
                  onClick={() => toggleDirection('SELL')} 
                  className={`flex-1 md:px-10 py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-3 ${direction === 'SELL' ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-500 hover:text-slate-400'}`}
                >
                  <ArrowDownCircle size={18} /> SELL
                </button>
                <button 
                  onClick={() => toggleDirection('BUY')} 
                  className={`flex-1 md:px-10 py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-3 ${direction === 'BUY' ? 'bg-emerald-500 text-white shadow-lg' : 'text-slate-500 hover:text-slate-400'}`}
                >
                  <ArrowUpCircle size={18} /> BUY
                </button>
             </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-7 space-y-6">
                <div className="bg-slate-900 rounded-3xl p-8 border border-slate-800 shadow-2xl space-y-8">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-3 block">Account Balance</label>
                            <div className="relative">
                                <DollarSign size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                <input 
                                  type="number" 
                                  value={balance}
                                  onChange={(e) => setBalance(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 pl-10 pr-4 text-white focus:border-gold-500 outline-none transition-all" 
                                />
                            </div>
                        </div>
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-3 block">Entry Price</label>
                            <input 
                              type="number" 
                              value={entryPrice}
                              step={instrument.pipSize}
                              onChange={(e) => handleEntryPriceChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 px-4 text-white focus:border-gold-500 outline-none font-mono text-lg transition-all" 
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 pt-2">
                        <div className={`group ${calcMode === 'FIXED_RISK' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-4 rounded-2xl transition-all border border-transparent`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-3 block group-hover:text-gold-400">Risk Amount ($)</label>
                            <input 
                              type="number" 
                              value={riskAmount}
                              onChange={(e) => handleRiskAmountChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2.5 px-3 text-white focus:border-gold-500 outline-none transition-all" 
                            />
                        </div>
