                                <input 
                                  type="number" 
                                  value={slPrice}
                                  step={instrument.pipSize}
                                  onChange={(e) => handleSlPriceChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 px-4 text-white outline-none focus:border-rose-500 transition-all font-mono" 
                                />
                            </div>
                        </div>
                    </div>

                    <div className="bg-slate-900 rounded-3xl p-8 border border-slate-800 shadow-xl relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-1 h-full bg-emerald-500"></div>
                        <div className="flex items-center gap-3 mb-6 text-emerald-400">
                            <Target size={20} />
                            <h3 className="font-bold uppercase text-sm tracking-widest">Take Profit</h3>
                        </div>
                        <div className="space-y-6">
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-2 uppercase font-bold tracking-wider">Distance ({unitLabel})</label>
                                <input 
                                  type="number" 
                                  value={tpDistance}
                                  onChange={(e) => handleTpDistChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 px-4 text-white outline-none focus:border-emerald-500 transition-all font-mono" 
                                />
                            </div>
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-2 uppercase font-bold tracking-wider">Exact Price</label>
                                <input 
                                  type="number" 
                                  value={tpPrice}
                                  step={instrument.pipSize}
                                  onChange={(e) => handleTpPriceChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 px-4 text-white outline-none focus:border-emerald-500 transition-all font-mono" 
                                />
                            </div>
                        </div>
