                    </div>

                    <div className="relative z-10 space-y-10">
                        <div>
                            <h3 className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
                                <Activity size={16} className="text-gold-500" />
                                Risk Allocation
                            </h3>
                            <div className="grid grid-cols-2 gap-6">
                                <div className="bg-slate-800/20 p-5 rounded-2xl border border-slate-700/30 backdrop-blur-sm">
                                    <p className="text-[10px] text-slate-500 uppercase font-bold mb-1 tracking-wider">Actual Risk</p>
                                    <p className="text-3xl font-serif text-rose-400">${riskAmount.toLocaleString()}</p>
                                </div>
                                <div className="bg-slate-800/20 p-5 rounded-2xl border border-slate-700/30 backdrop-blur-sm">
                                    <p className="text-[10px] text-slate-500 uppercase font-bold mb-1 tracking-wider">Potential PnL</p>
                                    <p className="text-3xl font-serif text-emerald-400">${rewardAmount.toLocaleString()}</p>
                                </div>
                            </div>
