                            <div className="flex justify-between items-center pb-3 border-b border-slate-800/50">
                                <span className="text-sm text-slate-400">Trade Lot Size</span>
                                <span className="text-2xl font-bold text-white">{lotSize.toFixed(isNikkei ? 0 : 2)} <span className="text-xs text-slate-500 font-normal ml-1">Lots</span></span>
