                            <div className="flex justify-between items-center pb-3 border-b border-slate-800/50">
                                <span className="text-sm text-slate-400">Value per {unitLabel}</span>
                                <span className="text-base font-mono text-slate-300">${(getValuePerUnit() * lotSize).toFixed(2)}</span>
                            </div>
                        </div>

                        <div className="pt-2">
                            <div className="bg-gold-500/5 border border-gold-500/10 p-5 rounded-2xl flex items-start gap-4">
                                <div className="p-3 bg-gold-500/20 rounded-xl text-gold-500">
                                    <CheckSquare size={24} />
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-gold-500 uppercase tracking-widest mb-1">Execution Ready</p>
                                    <p className="text-xs text-slate-400 leading-relaxed">
                                        {isNikkei ? "Nikkei 225 uses integer lots. " : ""}
                                        {rrRatio >= 2 
                                            ? "Mathematically sound setup. Risk is well managed."
                                            : "Reward profile is below institutional standards. Re-evaluate."}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="bg-slate-900/40 p-6 rounded-3xl border border-slate-800/60 flex items-center justify-between backdrop-blur-md">
                   <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-full bg-slate-800 flex items-center justify-center text-slate-500">
                        <Scale size={20} />
                      </div>
                      <div>
                        <p className="text-[10px] text-slate-500 uppercase font-black tracking-tighter">Notational Exposure</p>
                        <p className="text-sm font-mono text-slate-400 font-bold">${(lotSize * instrument.contractSize * entryPrice / (isNikkei ? 150 : 1)).toLocaleString(undefined, {maximumFractionDigits: 0})}</p>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-xs font-bold text-slate-200">{(lotSize * 100).toFixed(0)}% Margin</p>
                      <p className="text-[9px] text-slate-600 uppercase font-bold tracking-widest">Est. Utilization</p>
                   </div>
                </div>
            </div>
        </div>
    </div>
  );
};

export default Calculator;

import React, { useState, useEffect, useMemo } from 'react';
import { INSTRUMENTS } from '../constants';
import { Instrument, AccountSettings } from '../types';
import { 
  DollarSign, 
  Percent, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Target, 
  CheckSquare,
  TrendingUp,
  Scale,
  Activity,
  Zap
} from 'lucide-react';

interface CalculatorProps {
  settings: AccountSettings;
}

type CalcMode = 'FIXED_RISK' | 'FIXED_LOTS';

const Calculator: React.FC<CalculatorProps> = ({ settings }) => {
  const [instrument, setInstrument] = useState<Instrument>(INSTRUMENTS.find(i => i.symbol === '225JPY') || INSTRUMENTS[0]);
  const [direction, setDirection] = useState<'BUY' | 'SELL'>('SELL');
  const [calcMode, setCalcMode] = useState<CalcMode>('FIXED_LOTS'); // Default to lots for indices as per user focus
  const [balance, setBalance] = useState<number>(settings.balance);
  const [lotSize, setLotSize] = useState<number>(1.00);
  const [riskAmount, setRiskAmount] = useState<number>(0);
  const [riskPercent, setRiskPercent] = useState<number>(1);
  const [entryPrice, setEntryPrice] = useState<number>(0);

  const [slDistance, setSlDistance] = useState<number>(20);
  const [slPrice, setSlPrice] = useState<number>(0);

  const [tpDistance, setTpDistance] = useState<number>(40);
  const [tpPrice, setTpPrice] = useState<number>(0);

  const [rewardAmount, setRewardAmount] = useState<number>(0);
  const [rrRatio, setRrRatio] = useState<number>(0);

  const isIndex = instrument.type === 'INDEX';
  const unitLabel = isIndex ? 'Points' : 'Pips';
  const isNikkei = instrument.symbol === '225JPY';

  const pricePrecision = useMemo(() => {
    if (isNikkei) return 0;
    if (instrument.symbol.includes('JPY') || instrument.pipSize === 1) return 2;
    if (instrument.symbol === 'XAUUSD') return 2;
    return 5;
  }, [instrument, isNikkei]);

  const getValuePerUnit = () => {
    // Current market approx to match the user screenshot (8 points = $0.05 @ 1 lot)
    // 0.05 / 8 = 0.00625.  1 / 0.00625 = 160.00.
    const USDJPY = 160.00; 

    if (instrument.type === 'FOREX') {
       const pipValueInQuote = instrument.contractSize * instrument.pipSize;
       if (instrument.symbol.endsWith('USD')) return pipValueInQuote;
       if (instrument.symbol.includes('JPY')) return pipValueInQuote / USDJPY;
       return 10;
    }

    if (instrument.symbol === 'XAUUSD') {
        return instrument.contractSize * instrument.pipSize; 
    }

    if (instrument.type === 'INDEX') {
        const pointValueInQuote = instrument.contractSize * instrument.pipSize;
        if (isNikkei) {
            // 1 Point = 1 JPY. Convert to USD.
            return pointValueInQuote / USDJPY;
        }
        return pointValueInQuote; 
    }

    return instrument.contractSize * instrument.pipSize; 
  };

  const syncCalculations = (
    mode: CalcMode, 
    riskAmt: number, 
    lots: number, 
    dist: number, 
    bal: number
  ) => {
    const valPerUnit = getValuePerUnit();
    if (dist <= 0) return;

    if (mode === 'FIXED_RISK') {
      let calculatedLots = riskAmt / (dist * valPerUnit);

      if (isNikkei) {
        // Enforce 1.00 LS Minimum and Integer steps
        calculatedLots = Math.max(1, Math.round(calculatedLots));
        setLotSize(calculatedLots);
        const actualRisk = calculatedLots * dist * valPerUnit;
        setRiskAmount(Number(actualRisk.toFixed(2)));
        setRiskPercent(Number(((actualRisk / bal) * 100).toFixed(2)));
      } else {
        setLotSize(Number(calculatedLots.toFixed(2)));
        setRiskPercent(Number(((riskAmt / bal) * 100).toFixed(2)));
      }
    } else {
      const calculatedRisk = lots * dist * valPerUnit;
      setRiskAmount(Number(calculatedRisk.toFixed(2)));
      setRiskPercent(Number(((calculatedRisk / bal) * 100).toFixed(2)));
    }
  };

  useEffect(() => {
    const defaults: Record<string, number> = {
        'EURUSD': 1.0850, 'US30': 39500, 'NAS100': 18200, 'SPX500': 5200,
        '225JPY': 52850, 'XAUUSD': 2350, 'USDJPY': 151.00, 'EURJPY': 163.50, 'USDMXN': 16.50
    };

    const defaultSl = isIndex ? (isNikkei ? 100 : 50) : (instrument.symbol === 'USDMXN' ? 500 : 20);
    const defaultTp = defaultSl * 2;

    const price = defaults[instrument.symbol] || 0;
    setEntryPrice(price);
    setSlDistance(defaultSl);
    setTpDistance(defaultTp);

    const valPerUnit = getValuePerUnit();
    const initLots = isNikkei ? Math.max(1, lotSize) : 0.1;
    setLotSize(initLots);

    const calculatedRisk = initLots * defaultSl * valPerUnit;
    setRiskAmount(Number(calculatedRisk.toFixed(2)));
    setRiskPercent(Number(((calculatedRisk / balance) * 100).toFixed(2)));

    const slPriceDist = defaultSl * instrument.pipSize;
    const tpPriceDist = defaultTp * instrument.pipSize;
    setSlPrice(Number((direction === 'BUY' ? price - slPriceDist : price + slPriceDist).toFixed(pricePrecision)));
    setTpPrice(Number((direction === 'BUY' ? price + tpPriceDist : price - tpPriceDist).toFixed(pricePrecision)));
  }, [instrument]);

  useEffect(() => {
    const valPerUnit = getValuePerUnit();
    const reward = lotSize * tpDistance * valPerUnit;
    setRewardAmount(Number(reward.toFixed(2)));
    if (riskAmount > 0) {
      setRrRatio(Number((reward / riskAmount).toFixed(2)));
    }
  }, [tpDistance, lotSize, riskAmount, instrument]);

  const handleRiskAmountChange = (val: number) => {
    setCalcMode('FIXED_RISK');
    setRiskAmount(val);
    syncCalculations('FIXED_RISK', val, lotSize, slDistance, balance);
  };

  const handleRiskPercentChange = (val: number) => {
    setCalcMode('FIXED_RISK');
    setRiskPercent(val);
    const amt = balance * (val / 100);
    setRiskAmount(amt);
    syncCalculations('FIXED_RISK', amt, lotSize, slDistance, balance);
  };

  const handleLotChange = (val: number) => {
    setCalcMode('FIXED_LOTS');
    const sanitizedVal = isNikkei ? Math.max(1, Math.round(val)) : val;
    setLotSize(sanitizedVal);
    syncCalculations('FIXED_LOTS', riskAmount, sanitizedVal, slDistance, balance);
  };

  const handleSlDistChange = (dist: number) => {
    setSlDistance(dist);
    const priceDist = dist * instrument.pipSize;
    setSlPrice(Number((direction === 'BUY' ? entryPrice - priceDist : entryPrice + priceDist).toFixed(pricePrecision)));
    syncCalculations(calcMode, riskAmount, lotSize, dist, balance);
  };

  const handleSlPriceChange = (price: number) => {
    setSlPrice(price);
    const dist = Math.abs(entryPrice - price) / instrument.pipSize;
    setSlDistance(Number(dist.toFixed(1)));
    syncCalculations(calcMode, riskAmount, lotSize, dist, balance);
  };

  const handleTpDistChange = (dist: number) => {
    setTpDistance(dist);
    const priceDist = dist * instrument.pipSize;
    setTpPrice(Number((direction === 'BUY' ? entryPrice + priceDist : entryPrice - priceDist).toFixed(pricePrecision)));
  };

  const handleTpPriceChange = (price: number) => {
    setTpPrice(price);
    const dist = Math.abs(entryPrice - price) / instrument.pipSize;
    setTpDistance(Number(dist.toFixed(1)));
  };

  const handleEntryPriceChange = (price: number) => {
    setEntryPrice(price);
    const slP = direction === 'BUY' ? price - (slDistance * instrument.pipSize) : price + (slDistance * instrument.pipSize);
    const tpP = direction === 'BUY' ? price + (tpDistance * instrument.pipSize) : price - (tpDistance * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  };

  const toggleDirection = (dir: 'BUY' | 'SELL') => {
    setDirection(dir);
    const slP = dir === 'BUY' ? entryPrice - (slDistance * instrument.pipSize) : entryPrice + (slDistance * instrument.pipSize);
    const tpP = dir === 'BUY' ? entryPrice + (tpDistance * instrument.pipSize) : entryPrice - (tpDistance * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  };

  return (
    <div className="w-full animate-fade-in pb-20">
        <div className="flex flex-col md:flex-row justify-between items-center mb-8 gap-4">
             <div className="relative w-full md:w-auto">
                 <select 
                    value={instrument.symbol}
                    onChange={(e) => setInstrument(INSTRUMENTS.find(i => i.symbol === e.target.value) || INSTRUMENTS[0])}
                    className="w-full md:w-auto appearance-none bg-slate-900 border border-slate-700 text-gold-400 font-bold py-3 px-10 pr-14 rounded-xl text-sm outline-none focus:border-gold-500 transition-all cursor-pointer shadow-lg"
                 >
                    {INSTRUMENTS.map(i => <option key={i.symbol} value={i.symbol}>{i.symbol}</option>)}
                 </select>
                 <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                    <Activity size={18} />
                 </div>
             </div>

             <div className="flex bg-slate-900 p-1.5 rounded-2xl border border-slate-800 w-full md:w-auto shadow-inner">
                <button 
                  onClick={() => toggleDirection('SELL')} 
                  className={`flex-1 md:px-10 py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-3 ${direction === 'SELL' ? 'bg-rose-500 text-white shadow-lg' : 'text-slate-500 hover:text-slate-400'}`}
                >
                  <ArrowDownCircle size={18} /> SELL
                </button>
                <button 
                  onClick={() => toggleDirection('BUY')} 
                  className={`flex-1 md:px-10 py-3 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-3 ${direction === 'BUY' ? 'bg-emerald-500 text-white shadow-lg' : 'text-slate-500 hover:text-slate-400'}`}
                >
                  <ArrowUpCircle size={18} /> BUY
                </button>
             </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
            <div className="lg:col-span-7 space-y-6">
                <div className="bg-slate-900 rounded-3xl p-8 border border-slate-800 shadow-2xl space-y-8">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-3 block">Account Balance</label>
                            <div className="relative">
                                <DollarSign size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                <input 
                                  type="number" 
                                  value={balance}
                                  onChange={(e) => setBalance(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 pl-10 pr-4 text-white focus:border-gold-500 outline-none transition-all" 
                                />
                            </div>
                        </div>
                        <div>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-3 block">Entry Price</label>
                            <input 
                              type="number" 
                              value={entryPrice}
                              step={instrument.pipSize}
                              onChange={(e) => handleEntryPriceChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 px-4 text-white focus:border-gold-500 outline-none font-mono text-lg transition-all" 
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 pt-2">
                        <div className={`group ${calcMode === 'FIXED_RISK' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-4 rounded-2xl transition-all border border-transparent`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-3 block group-hover:text-gold-400">Risk Amount ($)</label>
                            <input 
                              type="number" 
                              value={riskAmount}
                              onChange={(e) => handleRiskAmountChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2.5 px-3 text-white focus:border-gold-500 outline-none transition-all" 
                            />
                        </div>
                        <div className={`group ${calcMode === 'FIXED_RISK' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-4 rounded-2xl transition-all border border-transparent`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-3 block group-hover:text-gold-400">Risk %</label>
                            <div className="relative">
                                <Percent size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                <input 
                                  type="number" 
                                  value={riskPercent}
                                  onChange={(e) => handleRiskPercentChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2.5 px-3 text-white focus:border-gold-500 outline-none transition-all" 
                                />
                            </div>
                        </div>
                        <div className={`group ${calcMode === 'FIXED_LOTS' ? 'ring-1 ring-gold-500/50 bg-gold-500/5' : ''} p-4 rounded-2xl transition-all border border-transparent`}>
                            <label className="text-[10px] uppercase text-slate-500 font-bold tracking-widest mb-3 block group-hover:text-gold-400">Lot Size</label>
                            <input 
                              type="number" 
                              step={isNikkei ? "1" : "0.01"}
                              min={isNikkei ? "1" : "0.01"}
                              value={lotSize}
                              onChange={(e) => handleLotChange(Number(e.target.value))}
                              className="w-full bg-slate-950 border border-slate-700 rounded-xl py-2.5 px-3 text-white focus:border-gold-500 outline-none font-bold text-gold-400 text-lg transition-all" 
                            />
                            {isNikkei && <span className="text-[9px] text-gold-600/60 uppercase block mt-1 font-bold">Nikkei: 1.00 LS Min</span>}
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
                    <div className="bg-slate-900 rounded-3xl p-8 border border-slate-800 shadow-xl relative overflow-hidden">
                        <div className="absolute top-0 left-0 w-1 h-full bg-rose-500"></div>
                        <div className="flex items-center gap-3 mb-6 text-rose-400">
                            <TrendingUp className="rotate-180" size={20} />
                            <h3 className="font-bold uppercase text-sm tracking-widest">Stop Loss</h3>
                        </div>
                        <div className="space-y-6">
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-2 uppercase font-bold tracking-wider">Distance ({unitLabel})</label>
                                <input 
                                  type="number" 
                                  value={slDistance}
                                  onChange={(e) => handleSlDistChange(Number(e.target.value))}
                                  className="w-full bg-slate-950 border border-slate-700 rounded-xl py-3 px-4 text-white outline-none focus:border-rose-500 transition-all font-mono" 
                                />
                            </div>
                            <div>
                                <label className="text-[10px] text-slate-500 block mb-2 uppercase font-bold tracking-wider">Exact Price</label>
                                <input 
