import React, { useState, useEffect, useMemo } from 'react';
import { INSTRUMENTS } from '../constants';
import { Instrument, AccountSettings } from '../types';
import { 
  DollarSign, 
  Percent, 
  ArrowUpCircle, 
  ArrowDownCircle, 
  Target, 
  CheckSquare,
  TrendingUp,
  Activity,
  Zap,
  ShieldCheck,
  Info
} from 'lucide-react';

interface CalculatorProps {
  settings: AccountSettings;
}

const Calculator: React.FC<CalculatorProps> = ({ settings }) => {
  const [instrument, setInstrument] = useState<Instrument>(INSTRUMENTS.find(i => i.symbol === '225JPY') || INSTRUMENTS[0]);
  const [direction, setDirection] = useState<'BUY' | 'SELL'>('SELL');
  const [balance, setBalance] = useState<number>(settings.balance);

  // Custom Contract Size for Indices (Broker 1: 1x, Broker 2: 100x, Broker 3: 1000x)
  const [contractSize, setContractSize] = useState<number>(100);

  // Independent Inputs
  const [riskAmount, setRiskAmount] = useState<string>('10');
  const [riskPercent, setRiskPercent] = useState<string>('0.1');
  const [lotSize, setLotSize] = useState<string>('0.06');
  const [calcMode, setCalcMode] = useState<'RISK' | 'LOTS'>('LOTS');

  const [entryPrice, setEntryPrice] = useState<number>(0);
  const [slDistance, setSlDistance] = useState<number>(20);
  const [slPrice, setSlPrice] = useState<number>(0);
  const [tpDistance, setTpDistance] = useState<number>(40);
  const [tpPrice, setTpPrice] = useState<number>(0);

  const isNikkei = instrument.symbol === '225JPY';
  const isIndex = instrument.type === 'INDEX';
  const unitLabel = isIndex ? 'Points' : 'Pips';

  // Precision logic for display
  const pricePrecision = useMemo(() => {
    if (isNikkei) return 2;
    if (instrument.symbol.includes('JPY') || instrument.pipSize === 1) return 2;
    if (instrument.symbol === 'XAUUSD') return 2;
    return 5;
  }, [instrument, isNikkei]);

  // Point/Pip Value Calculation per 1.00 Lot
  const getUnitValuePerLot = () => {
    // Exchange rate based on average from screenshots (~158.00 USDJPY)
    const USDJPY = 157.85; 

    if (isIndex) {
        return (contractSize * instrument.pipSize) / USDJPY;
    }

    if (instrument.type === 'FOREX') {
       const pipValueInQuote = instrument.contractSize * instrument.pipSize;
       if (instrument.symbol.endsWith('USD')) return pipValueInQuote;
       if (instrument.symbol.includes('JPY')) return pipValueInQuote / USDJPY;
       return 10;
    }

    if (instrument.symbol === 'XAUUSD') return instrument.contractSize * instrument.pipSize;
    return instrument.contractSize * instrument.pipSize;
  };

  // derived values for the summary panel
  const results = useMemo(() => {
    const unitValPerLot = getUnitValuePerLot();
    const numRiskAmt = parseFloat(riskAmount) || 0;

    let finalLots = 0;
    let actualRisk = 0;

    if (calcMode === 'RISK') {
      const rawLots = numRiskAmt / (slDistance * unitValPerLot);
      finalLots = Math.max(0.01, Math.floor(rawLots * 100) / 100);
      actualRisk = finalLots * slDistance * unitValPerLot;
    } else {
      finalLots = Math.max(0.01, parseFloat(lotSize) || 0);
      actualRisk = finalLots * slDistance * unitValPerLot;
    }

    const reward = finalLots * tpDistance * unitValPerLot;
    const rr = actualRisk > 0 ? (reward / actualRisk).toFixed(2) : '0';

    return {
      lots: finalLots,
      risk: actualRisk,
      reward: reward,
      rr: rr,
      valuePerUnit: finalLots * unitValPerLot
    };
  }, [riskAmount, lotSize, calcMode, slDistance, tpDistance, instrument, balance, contractSize]);

  useEffect(() => {
    const defaults: Record<string, number> = {
        'EURUSD': 1.0850, 'US30': 39500, 'NAS100': 18200, 'SPX500': 5200,
        '225JPY': 53147.0, 'XAUUSD': 2350, 'USDJPY': 151.00, 'EURJPY': 163.50, 'USDMXN': 16.50
