    let actualRisk = 0;

    if (calcMode === 'RISK') {
      const rawLots = numRiskAmt / (slDistance * unitValPerLot);
      finalLots = Math.max(0.01, Math.floor(rawLots * 100) / 100);
      actualRisk = finalLots * slDistance * unitValPerLot;
    } else {
      finalLots = Math.max(0.01, parseFloat(lotSize) || 0);
      actualRisk = finalLots * slDistance * unitValPerLot;
    }

    const reward = finalLots * tpDistance * unitValPerLot;
    const rr = actualRisk > 0 ? (reward / actualRisk).toFixed(2) : '0';

    return {
      lots: finalLots,
      risk: actualRisk,
      reward: reward,
      rr: rr,
      valuePerUnit: finalLots * unitValPerLot
    };
  }, [riskAmount, lotSize, calcMode, slDistance, tpDistance, instrument, balance, contractSize]);

  useEffect(() => {
    const defaults: Record<string, number> = {
        'EURUSD': 1.0850, 'US30': 39500, 'NAS100': 18200, 'SPX500': 5200,
        '225JPY': 53147.0, 'XAUUSD': 2350, 'USDJPY': 151.00, 'EURJPY': 163.50, 'USDMXN': 16.50
    };
    const price = defaults[instrument.symbol] || 0;
    const defaultSl = isNikkei ? 50 : (isIndex ? 50 : 20);

    if (isIndex) setContractSize(instrument.contractSize);

    setEntryPrice(price);
    setSlDistance(defaultSl);
    setTpDistance(defaultSl * 2);

    const slP = direction === 'BUY' ? price - (defaultSl * instrument.pipSize) : price + (defaultSl * instrument.pipSize);
    const tpP = direction === 'BUY' ? price + (defaultSl * 2 * instrument.pipSize) : price - (defaultSl * 2 * instrument.pipSize);
    setSlPrice(Number(slP.toFixed(pricePrecision)));
    setTpPrice(Number(tpP.toFixed(pricePrecision)));
  }, [instrument]);

  const handleRiskAmountChange = (val: string) => {
    setCalcMode('RISK');
    setRiskAmount(val);
    const num = parseFloat(val);
    if (!isNaN(num) && balance > 0) {
